-- Eutech Instruments (part of Thermo Fisher Scientific) 150 & 450 Series waterproof handheld meters: 21 order codes.
-- pH 150, CON 150, pH 450, CON 450, DO 450, PD 450 and PC 450 — meter only, meter & electrode, and meter kits.
-- From the Eutech 150 & 450 Series brochure. Photos: public/products/eutech/, logo: public/brands/eutech-instruments.png.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU (= order code).
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Eutech Instruments', 'eutech-instruments', 'https://www.eutechinst.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Environmental Equipment', 'environmental-equipment', 6) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('ECPHWP15000', 'Eutech pH 150 Waterproof pH Meter – Meter Only', 'eutech-ph-150-ph-meter-meter-only-ecphwp15000', 'The Eutech pH 150 (pH / mV / temperature) is an IP67 waterproof handheld pH / mV / temperature meter, the best-value meter in the Eutech waterproof range. This meter only configuration (order code ECPHWP15000) comes with: meter, Grip-Clip™ and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECPHWP15000"], ["Part no.", "01X651607"], ["Parameters", "pH / mV / temperature"], ["Supplied with", "Meter, Grip-Clip™ and two AA batteries"], ["pH range", "-2.00 to 16.00 pH"], ["pH resolution", "0.01 pH"], ["pH accuracy", "±0.01 pH"], ["pH calibration", "Up to 5 points (USA, NIST) or 6 points (DIN)"], ["mV range", "±2000 mV"], ["mV resolution", "0.1 mV within ±999.9 mV; 1 mV beyond"], ["mV accuracy", "±0.2 mV +2 LSD or ±0.5 % of reading, whichever is greater"], ["mV calibration", "±200 mV"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Display", "Three-line custom LCD"], ["Memory", "150 data sets"], ["Power", "Two AA batteries (included), >700 hours continuous use; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large three-line LCD shows pH or mV with temperature and % slope", "Auto buffer recognition for USA, NIST or DIN buffer sets", "Calibration due alarm reminds you when to recalibrate", "mV offset for Redox/ORP calibration or electrode checks", "Ready indicator, auto or manual hold and optional auto shut-off", "Built-in stand with wall-mount option", "Grip-Clip™ electrode holder secures the electrode to your beaker", "Works with any pH electrode with a BNC connector"]', 'environmental-equipment', '/products/eutech/ph-150.jpg'),
  ('ECPHWP15002', 'Eutech pH 150 Waterproof pH Meter – Meter & Electrode', 'eutech-ph-150-ph-meter-meter-electrode-ecphwp15002', 'The Eutech pH 150 (pH / mV / temperature) is an IP67 waterproof handheld pH / mV / temperature meter, the best-value meter in the Eutech waterproof range. This meter & electrode configuration (order code ECPHWP15002) comes with: meter, double-junction pH electrode (ECFC7252201B), ATC probe (PHWPTEM01W), Grip-Clip™ and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECPHWP15002"], ["Part no.", "01X651608"], ["Parameters", "pH / mV / temperature"], ["Supplied with", "Meter, double-junction pH electrode (ECFC7252201B), ATC probe (PHWPTEM01W), Grip-Clip™ and two AA batteries"], ["pH range", "-2.00 to 16.00 pH"], ["pH resolution", "0.01 pH"], ["pH accuracy", "±0.01 pH"], ["pH calibration", "Up to 5 points (USA, NIST) or 6 points (DIN)"], ["mV range", "±2000 mV"], ["mV resolution", "0.1 mV within ±999.9 mV; 1 mV beyond"], ["mV accuracy", "±0.2 mV +2 LSD or ±0.5 % of reading, whichever is greater"], ["mV calibration", "±200 mV"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Display", "Three-line custom LCD"], ["Memory", "150 data sets"], ["Power", "Two AA batteries (included), >700 hours continuous use; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large three-line LCD shows pH or mV with temperature and % slope", "Auto buffer recognition for USA, NIST or DIN buffer sets", "Calibration due alarm reminds you when to recalibrate", "mV offset for Redox/ORP calibration or electrode checks", "Ready indicator, auto or manual hold and optional auto shut-off", "Built-in stand with wall-mount option", "Grip-Clip™ electrode holder secures the electrode to your beaker", "Works with any pH electrode with a BNC connector"]', 'environmental-equipment', '/products/eutech/ph-150.jpg'),
  ('ECPHWP15002K', 'Eutech pH 150 Waterproof pH Meter – Meter Kit', 'eutech-ph-150-ph-meter-meter-kit-ecphwp15002k', 'The Eutech pH 150 (pH / mV / temperature) is an IP67 waterproof handheld pH / mV / temperature meter, the best-value meter in the Eutech waterproof range. This meter kit configuration (order code ECPHWP15002K) comes with: meter, double-junction pH electrode, ATC probe, Grip-Clip™, two AA batteries, hard carry case, pH buffers, storage solution and rinse solution. Covered by a 3-year meter warranty.', '[["Order code", "ECPHWP15002K"], ["Part no.", "01X651609"], ["Parameters", "pH / mV / temperature"], ["Supplied with", "Meter, double-junction pH electrode, ATC probe, Grip-Clip™, two AA batteries, hard carry case, pH buffers, storage solution and rinse solution"], ["pH range", "-2.00 to 16.00 pH"], ["pH resolution", "0.01 pH"], ["pH accuracy", "±0.01 pH"], ["pH calibration", "Up to 5 points (USA, NIST) or 6 points (DIN)"], ["mV range", "±2000 mV"], ["mV resolution", "0.1 mV within ±999.9 mV; 1 mV beyond"], ["mV accuracy", "±0.2 mV +2 LSD or ±0.5 % of reading, whichever is greater"], ["mV calibration", "±200 mV"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Display", "Three-line custom LCD"], ["Memory", "150 data sets"], ["Power", "Two AA batteries (included), >700 hours continuous use; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large three-line LCD shows pH or mV with temperature and % slope", "Auto buffer recognition for USA, NIST or DIN buffer sets", "Calibration due alarm reminds you when to recalibrate", "mV offset for Redox/ORP calibration or electrode checks", "Ready indicator, au