  ('ECCONWP15003', 'Eutech CON 150 Waterproof Conductivity Meter – Meter & Electrode', 'eutech-con-150-conductivity-meter-meter-electrode-ecconwp15003', 'The Eutech CON 150 (conductivity / TDS / temperature) is an IP67 waterproof handheld conductivity / TDS / temperature meter, the best-value conductivity meter in the Eutech waterproof range. This meter & electrode configuration (order code ECCONWP15003) comes with: meter, conductivity/ATC cell K = 1.0 (CONSEN91W), Grip-Clip™ and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECCONWP15003"], ["Part no.", "01X651611"], ["Parameters", "conductivity / TDS / temperature"], ["Supplied with", "Meter, conductivity/ATC cell K = 1.0 (CONSEN91W), Grip-Clip™ and two AA batteries"], ["Conductivity range", "0 to 200 mS"], ["Conductivity resolution", "0.01 µS to 0.1 mS"], ["Conductivity accuracy", "±1 % full scale"], ["Conductivity calibration", "Auto or manual; 1 point per range"], ["TDS range", "0 to 200 ppt (TDS factor 1.0)"], ["TDS resolution", "0.01 ppm to 0.1 ppt"], ["TDS accuracy", "±1 % full scale"], ["TDS factor", "Adjustable 0.4 to 1.0"], ["Cell constant", "0.1, 1.0 or 10"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Temperature coefficient", "0.0 to 10.0 %/°C (0 % for USP non-compensated readings)"], ["Display", "Three-line custom LCD"], ["Memory", "150 data sets"], ["Power", "Two AA batteries (included), >500 hours continuous use; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large three-line LCD shows conductivity or TDS with temperature and cell efficiency", "Automatic recognition of calibration standards, or manual calibration", "One-point or multi-point calibration (one point per range)", "Accepts probes with a 0.1, 1.0 or 10 cell constant", "Adjustable temperature coefficient, set to 0 % for USP methods", "Calibration due alarm", "Built-in stand with wall-mount option", "Easy-to-clean conductivity cell and Grip-Clip™ holder"]', 'environmental-equipment', '/products/eutech/con-150.jpg'),
  ('ECCONWP15003K', 'Eutech CON 150 Waterproof Conductivity Meter – Meter Kit', 'eutech-con-150-conductivity-meter-meter-kit-ecconwp15003k', 'The Eutech CON 150 (conductivity / TDS / temperature) is an IP67 waterproof handheld conductivity / TDS / temperature meter, the best-value conductivity meter in the Eutech waterproof range. This meter kit configuration (order code ECCONWP15003K) comes with: meter, conductivity/ATC cell K = 1.0, Grip-Clip™, two AA batteries, hard carry case and calibration solutions. Covered by a 3-year meter warranty.', '[["Order code", "ECCONWP15003K"], ["Part no.", "01X651612"], ["Parameters", "conductivity / TDS / temperature"], ["Supplied with", "Meter, conductivity/ATC cell K = 1.0, Grip-Clip™, two AA batteries, hard carry case and calibration solutions"], ["Conductivity range", "0 to 200 mS"], ["Conductivity resolution", "0.01 µS to 0.1 mS"], ["Conductivity accuracy", "±1 % full scale"], ["Conductivity calibration", "Auto or manual; 1 point per range"], ["TDS range", "0 to 200 ppt (TDS factor 1.0)"], ["TDS resolution", "0.01 ppm to 0.1 ppt"], ["TDS accuracy", "±1 % full scale"], ["TDS factor", "Adjustable 0.4 to 1.0"], ["Cell constant", "0.1, 1.0 or 10"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Temperature coefficient", "0.0 to 10.0 %/°C (0 % for USP non-compensated readings)"], ["Display", "Three-line custom LCD"], ["Memory", "150 data sets"], ["Power", "Two AA batteries (included), >500 hours continuous use; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large three-line LCD shows conductivity or TDS with temperature and cell efficiency", "Automatic recognition of cali