  ('ECPHWP45000', 'Eutech pH 450 Waterproof pH / Ion Meter – Meter Only', 'eutech-ph-450-ph-ion-meter-meter-only-ecphwp45000', 'The Eutech pH 450 (pH / mV / ION / temperature) is a backlit IP67 waterproof handheld pH / mV / ION / temperature meter built for field and lab use. This meter only configuration (order code ECPHWP45000) comes with: meter, Grip-Clip™ and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECPHWP45000"], ["Part no.", "01X651628"], ["Parameters", "pH / mV / ION / temperature"], ["Supplied with", "Meter, Grip-Clip™ and two AA batteries"], ["pH range", "-2.00 to 16.00 pH"], ["pH resolution", "0.01 pH"], ["pH accuracy", "±0.01 pH"], ["pH calibration", "Up to 5 points (USA, NIST, custom) or 6 points (DIN)"], ["mV range", "±2000 mV"], ["mV resolution", "0.1 mV within ±999.9 mV; 1 mV beyond"], ["mV accuracy", "±0.2 mV +2 LSD or ±0.5 % of reading, whichever is greater"], ["mV calibration", "±200 mV"], ["ION range", "0.0 to 2000 ppm"], ["ION resolution", "0.01 / 0.1 / 1 ppm"], ["ION accuracy", "±0.5 % full scale (monovalent); ±1 % full scale (divalent)"], ["ION calibration", "2 to 5 points"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Display", "Three-line custom LCD with backlight"], ["Memory", "500 data sets with date and time"], ["Output", "USB or RS232"], ["Real-time clock", "Time and date stamp on calibration and stored data (GLP)"], ["Power", "Two AA batteries (included), >500 hours without backlight; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large backlit display shows the reading with temperature and % slope", "Auto buffer recognition; up to 5 custom buffers for manual calibration", "Measures ion concentration (ppm) with an ion-selective electrode", "Stores 500 data sets with time and date stamp for GLP", "USB or RS232 output with optional data cables", "Calibration due alarm", "Built-in stand with wall-mount option", "Works with pH, ORP or ISE electrodes with a BNC connector"]', 'environmental-equipment', '/products/eutech/ph-450.jpg'),
  ('ECPHWP45002', 'Eutech pH 450 Waterproof pH / Ion Meter – Meter & Electrode', 'eutech-ph-450-ph-ion-meter-meter-electrode-ecphwp45002', 'The Eutech pH 450 (pH / mV / ION / temperature) is a backlit IP67 waterproof handheld pH / mV / ION / temperature meter built for field and lab use. This meter & electrode configuration (order code ECPHWP45002) comes with: meter, double-junction pH electrode (ECFC7252201B), ATC probe (PHWPTEM01W), Grip-Clip™ and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECPHWP45002"], ["Part no.", "01X651629"], ["Parameters", "pH / mV / ION / temperature"], ["Supplied with", "Meter, double-junction pH electrode (ECFC7252201B), ATC probe (PHWPTEM01W), Grip-Clip™ and two AA batteries"], ["pH range", "-2.00 to 16.00 pH"], ["pH resolution", "0.01 pH"], ["pH accuracy", "±0.01 pH"], ["pH calibration", "Up to 5 points (USA, NIST, custom) or 6 points (DIN)"], ["mV range", "±2000 mV"], ["mV resolution", "0.1 mV within ±999.9 mV; 1 mV beyond"], ["mV accuracy", "±0.2 mV +2 LSD or ±0.5 % of reading, whichever is greater"], ["mV calibration", "±200 mV"], ["ION range", "0.0 to 2000 ppm"], ["ION resolution", "0.01 / 0.1 / 1 ppm"], ["ION accuracy", "±0.5 % full scale (monovalent); ±1 % full scale (divalent)"], ["ION calibration", "2 to 5 points"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Display", "Three-line custom LCD with backlight"], ["Memory", "500 data sets with date and time"], ["Output", "USB or RS232"], ["Real-time clock", "Time and date stamp on calibration and stored data (GLP)"], ["Power", "Two AA batteries (included), >500 hours without backlight; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large backlit display shows the reading with temperature and % slope", "Auto buffer recognition; up to 5 custom buffers for manual calibration", "Measures ion concentration (ppm) with an ion-selective electrode", "Stores 500 data sets with time and date stamp for GLP", "USB or RS232 output with optional data cables", "Calibration due alarm", "Built-in stand with wall-mount option", "Works with pH, ORP or ISE electrodes with a BNC connector"]', 'environmental-equipment', '/products/eutech/ph-450.jpg'),
  ('ECPHWP45002K', 'Eutech pH 450 Waterproof pH / Ion Meter – Meter Kit', 'eutech-ph-450-ph-ion-meter-meter-kit-ecphwp45002k', 'The Eutech pH 450 (pH / mV / ION / temperature) is a backlit IP67 waterproof handheld pH / mV / ION / temperature meter built for field and lab use. This meter kit configuration (order code ECPHWP45002K) comes with: meter, double-junction pH electrode, ATC probe, Grip-Clip™, two AA batteries, hard carry case, USB cable, pH buffers, storage solution and rinse solution. Covered by a 3-year meter warranty.', '[["Order code", "ECPHWP45002K"], ["Part no.", "01X651630"], ["Parameters", "pH / mV / ION / temperature"], ["Supplied with", "Meter, double-junction pH electrode, ATC probe, Grip-Clip™, two AA batteries, hard carry case, USB cable, pH buffers, storage solution and rinse solution"], ["pH range", "-2.00 to 16.00 pH"], ["pH resolution", "0.01 pH"], ["pH accuracy", "±0.01 pH"], ["pH calibration", "Up to 5 points (USA, NIST, custom) or 6 points (DIN)"], ["mV range", "±2000 mV"], ["mV resolution", "0.1 mV within ±999.9 mV; 1 mV beyond"], ["mV accuracy", "±0.2 mV +2 LSD or ±0.5 % of reading, whichever is greater"], ["mV calibration", "±200 mV"], ["ION range", "0.0 to 2000 ppm"], ["ION resolution", "0.01 / 0.1 / 1 ppm"], ["ION accuracy", "±0.5 % full scale (monovalent); ±1 % full scale (divalent)"], ["ION calibration", "2 to 5 points"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Display", "Three-line custom LCD with backlight"], ["Memory", "500 data sets with date and time"], ["Output", "USB or RS232"], ["Real-time clock", "Time and date stamp on calibration and stored data (GLP)"], ["Power", "Two AA batteries (included), >500 hours without backlight; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large backlit display shows the reading with temperature and % slope", "Auto buffer recognition; up to 5 custom buffers for manual calibration", "Measures ion concentration (ppm) with an ion-selective electrode", "Stores 500 data sets with time and date stamp for GLP", "USB or RS232 output with optional data cables", "Calibration due alarm", "Built-in stand with wall-mount option", "Works with pH, ORP or ISE electrodes with a BNC connector"]', 'environmental-equipment', '/products/eutech/ph-450.jpg'),
  ('ECCONWP45003', 'Eutech CON 450 Waterproof Conductivity Meter – Meter & Electrode', 'eutech-con-450-conductivity-meter-meter-electrode-ecconwp45003', 'The Eutech CON 450 (conductivity / TDS / salinity / temperature) is a backlit IP67 waterproof handheld conductivity / TDS / salinity / temperature meter. This meter & electrode configuration (order code ECCONWP45003) comes with: meter, conductivity/ATC cell K = 1.0 (CONSEN91W), Grip-Clip™ and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECCONWP45003"], ["Part no.", "01X651632"], ["Parameters", "conductivity / TDS / salinity / temperature"], ["Supplied with", "Meter, conductivity/ATC cell K = 1.0 (CONSEN91W), Grip-Clip™ and two AA batteries"], ["Conductivity range", "0 to 200 mS"], ["Conductivity resolution", "0.01 µS to 0.1 mS"], ["Conductivity accuracy", "±1 % full scale"], ["Conductivity calibration", "Auto or manual; 1 point per range"], ["TDS range", "0 to 200 ppt (TDS factor 1.0)"], ["TDS resolution", "0.01 ppm to 0.1 ppt"], ["TDS accuracy", "±1 % full scale"], ["Salinity range", "0 to 50 ppt"], ["Salinity resolution", "0.01"], ["Salinity accuracy", "±1 % full scale"], ["TDS factor", "Adjustable 0.4 to 1.0"], ["Cell constant", "0.10, 1.00 or 10.0"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Temperature coefficient", "0.00 to 10.00 %/°C"], ["Display", "Three-line custom LCD with backlight"], ["Memory", "500 data sets with date and time"], ["Output", "USB or RS232"], ["Real-time clock", "Time and date stamp on calibration and stored data (GLP)"], ["Power", "Two AA batteries (included), >300 hours without backlight; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.