  ('ECCONWP45003K', 'Eutech CON 450 Waterproof Conductivity Meter – Meter Kit', 'eutech-con-450-conductivity-meter-meter-kit-ecconwp45003k', 'The Eutech CON 450 (conductivity / TDS / salinity / temperature) is a backlit IP67 waterproof handheld conductivity / TDS / salinity / temperature meter. This meter kit configuration (order code ECCONWP45003K) comes with: meter, conductivity/ATC cell K = 1.0, Grip-Clip™, two AA batteries, hard carry case, USB cable and calibration solutions. Covered by a 3-year meter warranty.', '[["Order code", "ECCONWP45003K"], ["Part no.", "01X651633"], ["Parameters", "conductivity / TDS / salinity / temperature"], ["Supplied with", "Meter, conductivity/ATC cell K = 1.0, Grip-Clip™, two AA batteries, hard carry case, USB cable and calibration solutions"], ["Conductivity range", "0 to 200 mS"], ["Conductivity resolution", "0.01 µS to 0.1 mS"], ["Conductivity accuracy", "±1 % full scale"], ["Conductivity calibration", "Auto or manual; 1 point per range"], ["TDS range", "0 to 200 ppt (TDS factor 1.0)"], ["TDS resolution", "0.01 ppm to 0.1 ppt"], ["TDS accuracy", "±1 % full scale"], ["Salinity range", "0 to 50 ppt"], ["Salinity resolution", "0.01"], ["Salinity accuracy", "±1 % full scale"], ["TDS factor", "Adjustable 0.4 to 1.0"], ["Cell constant", "0.10, 1.00 or 10.0"], ["Temperature range", "-10.0 to 110.0 °C (14.0 to 230.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic or manual, -10 to 110 °C"], ["Temperature coefficient", "0.00 to 10.00 %/°C"], ["Display", "Three-line custom LCD with backlight"], ["Memory", "500 data sets with date and time"], ["Output", "USB or RS232"], ["Real-time clock", "Time and date stamp on calibration and stored data (GLP)"], ["Power", "Two AA batteries (included), >300 hours without backlight; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Large backlit display shows the reading with temperature and cell efficiency", "Measures conductivity, TDS and salinity", "Automatic or manual calibration; one point or one point per range", "Selectable cell constant 0.10, 1.00 or 10.0", "Adjustable temperature coefficient, set to 0 % for USP methods", "Stores 500 data sets with time and date stamp for GLP", "USB or RS232 output with free communication software", "Built-in stand with wall-mount option"]', 'environmental-equipment', '/products/eutech/con-450.jpg'),
  ('ECDOWP45000', 'Eutech DO 450 Waterproof Dissolved Oxygen Meter – Meter Only', 'eutech-do-450-dissolved-oxygen-meter-meter-only-ecdowp45000', 'The Eutech DO 450 (optical dissolved oxygen / temperature) is a backlit IP67 waterproof handheld optical dissolved oxygen meter that uses maintenance-free RDO technology. This meter only configuration (order code ECDOWP45000) comes with: meter and two AA batteries. Covered by a 3-year meter warranty.', '[["Order code", "ECDOWP45000"], ["Part no.", "01X651634"], ["Parameters", "optical dissolved oxygen / temperature"], ["Supplied with", "Meter and two AA batteries"], ["DO range", "0 to 200 %; 0 to 20 ppm (mg/L)"], ["DO resolution", "0.1 %; 0.1 ppm (mg/L)"], ["DO accuracy", "±2 %; ±0.1 ppm up to 8 ppm; ±0.2 ppm above 8 ppm"], ["DO calibration", "Zero and saturation"], ["Pressure & salinity compensation", "Manual"], ["Temperature range", "0.0 to 50.0 °C (32.0 to 122.0 °F)"], ["Temperature resolution", "0.1 °C / °F"], ["Temperature accuracy", "±0.5 °C (±0.9 °F)"], ["Temperature calibration", "Offset in 0.1 steps, ±10 °C (±18 °F)"], ["Temperature compensation", "Automatic"], ["Display", "Three-line custom LCD with backlight"], ["Memory", "500 data sets with date and time"], ["Output", "USB or RS232"], ["Real-time clock", "Time and date stamp on calibration and stored data (GLP)"], ["Power", "Two AA batteries (included), >100 hours without backlight; optional 9 V AC adapter"], ["Protection", "IP67 waterproof and dustproof; floats"], ["Dimensions (L × W × H)", "20 × 8.3 × 5.7 cm"], ["Weight", "0.5 kg (meter)"]]', '["Optical RDO probe: no membranes or electrolyte to replace", "Switch between % saturation and mg/L (ppm) with one button", "Manual barometric pressure and salinity correction", "Calibration due alarm", "Stores 500 data sets with time and date stamp for GLP", "USB or RS232 output with optional data cables", "Built-in stand with wall-mount option"]', 'environmental-equipment', '/products/eutech/do-450.jpg'),
